-- Defense-in-depth triggers: derive hotelId under FOR NO KEY UPDATE SKIP LOCKED.
-- BookingRoom
DROP TRIGGER IF EXISTS trg_booking_room_hotel ON "BookingRoom";
CREATE OR REPLACE FUNCTION public.trg_booking_room_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_hotel_id text;
BEGIN
  SELECT "Booking"."hotelId" INTO v_hotel_id
    FROM "Booking"
   WHERE "Booking"."id" = NEW."bookingId"
   ORDER BY "Booking"."id"
   FOR NO KEY UPDATE OF "Booking" SKIP LOCKED;
  IF v_hotel_id IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for BookingRoom: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  NEW."hotelId" := v_hotel_id;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_booking_room_hotel BEFORE INSERT OR UPDATE OF "bookingId" ON "BookingRoom" FOR EACH ROW EXECUTE FUNCTION public.trg_booking_room_hotel();
